import{_ as e,o as a,c as i,a2 as s}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Gemini 从 brief 到成片的标准工作流模板","description":"","frontmatter":{},"headers":[],"relativePath":"tools/gemini-master-template.md","filePath":"tools/gemini-master-template.md","lastUpdated":1787456457000}'),o={name:"tools/gemini-master-template.md"};function n(r,t,l,d,p,c){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="gemini-从-brief-到成片的标准工作流模板" tabindex="-1">Gemini 从 brief 到成片的标准工作流模板 <a class="header-anchor" href="#gemini-从-brief-到成片的标准工作流模板" aria-label="Permalink to &quot;Gemini 从 brief 到成片的标准工作流模板&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">来源</p><ul><li>来源：Gemini Web（Google Gemini）现场问答</li><li>时间：2026-08-15</li><li>说明：本文为用户向 Gemini Web 提问拿到的回答，仅做排版整理，文字未做改写。内容由 Gemini 生成，未经 Google 官方文档逐一核实；涉及 Veo 的能力与参数请以官方文档为准。</li></ul></div><blockquote><p>提问：有没有一个从 brief 到成片的标准 prompt 工作流，能把「时长锁定 + 中英文分层 + 资产一致性 + 三层运镜解耦 + 排除项 + 中性参考图」串成一套固定模板？</p></blockquote><h2 id="_7-层标准模板" tabindex="-1">7 层标准模板 <a class="header-anchor" href="#_7-层标准模板" aria-label="Permalink to &quot;7 层标准模板&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[①时长与节奏锁定] + [②核心主体与资产一致性] + [③场景与光影氛围] + [④三层运镜解耦] + [⑤中英文分层描述] + [⑥排除项] + [⑦中性参考图 / 首尾帧指引]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>层</th><th>作用</th><th>要点</th></tr></thead><tbody><tr><td>① 时长锁定</td><td>秒数 / 帧率 / 动作时间轴</td><td><code>X 秒，60fps 慢动作</code>，时间轴闭合到总时长</td></tr><tr><td>② 资产一致性</td><td>锁主体 / 包装 / 配色不漂移</td><td>形态锚点 + 包装锚点 + 色值（如 #F4C430）</td></tr><tr><td>③ 场景与光影</td><td>定基调</td><td>光型 + 色调 + 氛围</td></tr><tr><td>④ 三层运镜解耦</td><td>相机 / 主体 / 物理分开写</td><td>主体动作、镜头轨道、光学参数三块隔离</td></tr><tr><td>⑤ 中英文分层</td><td>意境与术语分工</td><td>中文意境 + 英文摄影术语</td></tr><tr><td>⑥ 排除项</td><td>负向兜底</td><td><code>plastic look, deformed hands, blurry dust...</code></td></tr><tr><td>⑦ 中性参考图</td><td>首帧 / 控制帧</td><td>白底/暗底干净图，锁构图不锁风格</td></tr></tbody></table><h2 id="实战-prompt-模板-蜂蜜滴落薯条特写" tabindex="-1">实战 Prompt 模板（蜂蜜滴落薯条特写） <a class="header-anchor" href="#实战-prompt-模板-蜂蜜滴落薯条特写" aria-label="Permalink to &quot;实战 Prompt 模板（蜂蜜滴落薯条特写）&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【①时长】4 秒，120fps 慢动作；0-2s 蜂蜜滴落，2-4s 镜头环绕</span></span>
<span class="line"><span>【②资产】Premium crinkle-cut golden fries, fine honey-butter powder（#F4C430 + #FFBF00）</span></span>
<span class="line"><span>【③光影】Soft cinematic rim light, warm volumetric backlight, golden bokeh</span></span>
<span class="line"><span>【④三层运镜】Layer1 蜂蜜缓缓覆盖薯条；Layer2 45° 微距推入后 30° 环绕；Layer3 浅景深、清晰焦点、探针微距镜头</span></span>
<span class="line"><span>【⑤中英文】High-end commercial TVC, 8K, photorealistic, appetite appeal</span></span>
<span class="line"><span>【⑥排除】plastic texture, cartoonish, deformed fry shape, camera shake, text, watermark, fingers</span></span>
<span class="line"><span>【⑦参考图】白底/暗底的高清中性微距图做控制帧</span></span></code></pre></div><h2 id="_4-步-sop" tabindex="-1">4 步 SOP <a class="header-anchor" href="#_4-步-sop" aria-label="Permalink to &quot;4 步 SOP&quot;">​</a></h2><ol><li><strong>Gemini 拆 storyboard</strong>：输入产品特点，产出 3–5 个 3–4 秒镜头脚本（Hero / Action / Flavor explosion / Packaging reveal）。</li><li><strong>套 7 层模板</strong>：把镜头脚本填入模板，锁定每个镜头的 Duration、Camera Path、Asset Anchors。</li><li><strong>准备 1–2 张中性资产图</strong>：① 单个薯条/薯片极致微距图（无背景/暗底）；② 包装袋 3D 正面渲染图。</li><li><strong>Veo 生成 + 控帧</strong>：挂中性图做 Image Prompt / First Frame 生成 4 秒片段，导入剪辑拼接 + 音效成片。</li></ol><hr><p>关联：本模板是各单点的汇总——①时长见 <a href="/tools/gemini-video-duration">控制视频时长</a>、②资产见 <a href="/tools/gemini-shot-consistency">跨镜头一致性</a>、④三层见 <a href="/tools/gemini-motion-layers">三层运动解耦</a>、⑤语言见 <a href="/tools/gemini-prompt-language">中文还是英文</a>、⑥见 <a href="/tools/gemini-negative-tokens">排除项写法</a>、⑦见 <a href="/tools/gemini-reference-image">参考图去风格</a>。全链路上游见 <a href="/method/workflow-sop">从 brief 到成片 SOP</a>。</p>`,12)])])}const g=e(o,[["render",n]]);export{h as __pageData,g as default};
